"""Embed dashboard.html in the firmware as JagSeatCan/page_html.h. Run it after editing the page, then flash."""
import pathlib

root = pathlib.Path(__file__).parent
html = (root / "dashboard.html").read_text(encoding="utf-8")
assert ')HTML"' not in html, "page must not contain the raw-string terminator"
(root / "JagSeatCan" / "page_html.h").write_text(
    "// generated by make_page.py from dashboard.html - edit that file instead\n"
    f'static const char PAGE[] PROGMEM = R"HTML({html})HTML";\n', encoding="utf-8")
print(f"page_html.h written ({len(html)} bytes)")
